-- Esquema REAL de la base de datos de Orbit (Supabase), volcado el 11/11/2026.
-- Sirve para recrear la base de datos desde cero y como referencia. Idempotente.
-- Las columnas "id bigint not null" sin default son columnas identity (generated by default as identity).
-- Seguridad por fila: activada en TODAS las tablas, con política auth.uid() = user_id.
-- Tablas sin uso actual (se conservan): budgets, savings_goals (sustituidas por user_kv), operations,
-- networth_log, journal, pe_reports, watchlist. Social congelado: connections, shares, share_comments.

create table if not exists public.app_events (
  id bigint generated by default as identity primary key,
  user_id uuid references auth.users(id) on delete cascade,
  event text not null,
  props jsonb default '{}'::jsonb,
  day date default ((now() at time zone 'utc'))::date,
  created_at timestamptz default now()
);
alter table public.app_events enable row level security;
create unique index if not exists app_events_daily_session on public.app_events (user_id, day) where (event = 'session_start');
create index if not exists app_events_event_day on public.app_events (event, day);
create index if not exists app_events_user_day on public.app_events (user_id, day);

create table if not exists public.blocks (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  type text not null,              -- cash | bolsa | fondos | pe | inmobiliario | otros
  name text not null,
  value numeric default 0,
  eur_value numeric default 0,
  currency text default 'EUR',
  notes text default '',
  extra jsonb default '{}'::jsonb,  -- positions, pending_orders, applied, balance_date, PE: *_base, nav_official…
  deleted boolean default false,
  created_at timestamptz default now(),
  updated_at timestamptz default now()   -- se usa como versión (control de concurrencia)
);
alter table public.blocks enable row level security;
create index if not exists idx_blocks_user on public.blocks (user_id) where (deleted = false);

create table if not exists public.budgets (
  user_id uuid not null references auth.users(id) on delete cascade,
  category text not null,
  monthly_limit numeric not null check (monthly_limit > 0),
  updated_at timestamptz not null default now(),
  primary key (user_id, category)
);
alter table public.budgets enable row level security;

create table if not exists public.connections (
  id uuid primary key default gen_random_uuid(),
  user_a uuid not null references auth.users(id) on delete cascade,
  user_b uuid not null references auth.users(id) on delete cascade,
  status text not null default 'accepted',
  created_at timestamptz not null default now(),
  check (user_a < user_b),
  unique (user_a, user_b)
);
alter table public.connections enable row level security;

create table if not exists public.documents (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  filename text not null,
  doc_type text default 'otro',
  block_id bigint,
  extracted_data jsonb default '{}'::jsonb,
  ai_summary text default '',
  file_size integer default 0,
  created_at timestamptz default now(),
  storage_path text,
  extracted_text text
);
alter table public.documents enable row level security;
create index if not exists idx_docs_user on public.documents (user_id);

create table if not exists public.instinct_tokens (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  token_hash text not null unique,   -- sha256 del token; el token en claro nunca se guarda
  label text not null default 'Instinct',
  created_at timestamptz not null default now(),
  last_used_at timestamptz,
  revoked boolean not null default false
);
alter table public.instinct_tokens enable row level security;

create table if not exists public.journal (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  text text not null,
  patrimonio numeric,
  created_at timestamptz default now()
);
alter table public.journal enable row level security;

create table if not exists public.movements (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  date date not null,
  type text not null check (type in ('expense','income','buy','sell','saving')),
  amount numeric not null check (amount > 0),
  category text,                     -- 'cartera' = historial de operaciones actual
  concept text,
  ticker text,
  isin text,
  qty numeric,
  price numeric,
  currency text not null default 'EUR',
  goal_id uuid,
  source text not null default 'manual' check (source in ('manual','instinct','import','document','opening')),
  request_id text,
  created_at timestamptz not null default now(),
  deleted_at timestamptz
);
alter table public.movements enable row level security;
create unique index if not exists movements_request on public.movements (user_id, request_id) where (request_id is not null);
create index if not exists movements_user_date on public.movements (user_id, date) where (deleted_at is null);

create table if not exists public.networth_log (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  date date not null,
  patrimonio numeric, cartera numeric, cash numeric, robo numeric, pe numeric,
  created_at timestamptz default now(),
  unique (user_id, date)
);
alter table public.networth_log enable row level security;
create index if not exists idx_nw_user on public.networth_log (user_id, date desc);

create table if not exists public.notifications_sent (
  user_id uuid not null references auth.users(id) on delete cascade,
  key text not null,
  sent_at timestamptz not null default now(),
  primary key (user_id, key)
);
alter table public.notifications_sent enable row level security;

create table if not exists public.operations (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  date text not null, ticker text not null, name text, type text not null,
  qty numeric, price numeric, amount numeric not null, commission numeric default 0,
  broker text, currency text default 'USD', deleted boolean default false, cash_before numeric,
  created_at timestamptz default now()
);
alter table public.operations enable row level security;
create index if not exists idx_ops_user on public.operations (user_id);

create table if not exists public.patrimonio_history (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  date date not null,
  total numeric not null,
  by_block jsonb default '{}'::jsonb,
  created_at timestamptz default now(),
  unique (user_id, date)
);
alter table public.patrimonio_history enable row level security;
create index if not exists idx_history_user on public.patrimonio_history (user_id, date desc);

create table if not exists public.pe_reports (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  quarter text, date text, nav_total numeric, tu_nav numeric, tvpi numeric, dpi numeric, rvpi numeric,
  irr numeric, capital_llamado numeric, notes text, ai_analysis text,
  created_at timestamptz default now()
);
alter table public.pe_reports enable row level security;

create table if not exists public.pe_transactions (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  block_id bigint,
  kind text not null,                -- call | distribution | commitment
  amount numeric not null,
  date date not null,
  note text,                         -- lleva [req:<id>] cuando viene de Instinct
  created_at timestamptz default now()
);
alter table public.pe_transactions enable row level security;

create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  email text, full_name text,
  risk_profile text default 'moderate', investment_horizon text default 'long', primary_currency text default 'EUR',
  monthly_income numeric default 0, monthly_expenses numeric default 0,
  onboarding_completed boolean default false,
  created_at timestamptz default now(),
  goal text default 'growth', display_name text,
  invite_code text default lower(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10))
);
alter table public.profiles enable row level security;
create unique index if not exists profiles_invite_code_idx on public.profiles (invite_code);

create table if not exists public.push_subscriptions (
  endpoint text primary key,
  user_id uuid references auth.users(id) on delete cascade,
  subscription jsonb not null,
  lang text default 'es',
  level text default 'principiante',
  created_at timestamptz default now(),
  name text,
  tickers text[] default '{}',
  pref_daily boolean default true,
  pref_weekly boolean default true,
  pref_alerts boolean default true
);
alter table public.push_subscriptions enable row level security;

create table if not exists public.quick_expenses (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  amount numeric not null,
  category text not null,
  note text,
  occurred_at timestamptz default now(),
  created_at timestamptz default now()
);
alter table public.quick_expenses enable row level security;
create index if not exists quick_expenses_user_idx on public.quick_expenses (user_id);

create table if not exists public.quick_tokens (
  user_id uuid primary key references auth.users(id) on delete cascade,
  token text not null unique,
  created_at timestamptz default now()
);
alter table public.quick_tokens enable row level security;

create table if not exists public.savings_goals (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  name text not null,
  target numeric not null check (target > 0),
  deadline date,
  archived boolean not null default false,
  created_at timestamptz not null default now()
);
alter table public.savings_goals enable row level security;
create unique index if not exists savings_goals_name on public.savings_goals (user_id, lower(name)) where (not archived);

create table if not exists public.shares (
  id uuid primary key default gen_random_uuid(),
  from_user uuid not null references auth.users(id) on delete cascade,
  to_user uuid not null references auth.users(id) on delete cascade,
  from_name text, article jsonb not null, note text, reason text,
  created_at timestamptz not null default now()
);
alter table public.shares enable row level security;

create table if not exists public.share_comments (
  id uuid primary key default gen_random_uuid(),
  share_id uuid not null references public.shares(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  user_name text, text text not null,
  created_at timestamptz not null default now()
);
alter table public.share_comments enable row level security;

create table if not exists public.user_expense_data (
  user_id uuid primary key references auth.users(id) on delete cascade,
  data jsonb not null default '{}'::jsonb,   -- gastos por mes + _deleted (borrados, para sincronizar)
  updated_at timestamptz not null default now()   -- versión para control de concurrencia
);
alter table public.user_expense_data enable row level security;

create table if not exists public.user_kv (
  user_id uuid not null references auth.users(id) on delete cascade,
  key text not null,
  value text,
  deleted boolean not null default false,
  updated_at timestamptz not null default now(),
  primary key (user_id, key)
);
alter table public.user_kv enable row level security;

create table if not exists public.watchlist (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  ticker text not null, name text, type text, alert_price numeric, note text,
  added_at timestamptz default now()
);
alter table public.watchlist enable row level security;
